(function () {
  "use strict";

  // Logos Pré-Cadastradas (Vermelha e Azul) em base64.
  // Usadas na pré-visualização e no código HTML da Locaweb (não dependem de arquivo externo).
  const LOGO_RED = "data:image/png;base64,";
  const LOGO_BLUE = "data:image/jpeg;base64,";

  // Dimensões originais das logos oficiais (px)
  const OFFICIAL_LOGO_W = 589;
  const OFFICIAL_LOGO_H = 141;

  // URLs PÚBLICAS (https) das logos.
  // Quando preenchidas, passam a ser usadas TANTO na Locaweb QUANTO no Outlook,
  // no lugar do base64 e dos arquivos locais. É a opção mais confiável:
  // Gmail e Outlook (destinatários) bloqueiam imagens base64.
  // Ex.: "https://www.federalst.com.br/assinatura/logo-azul.jpg"
  const LOGO_URL_RED = "";
  const LOGO_URL_BLUE = "";

  // Arquivos de logo que ficam na MESMA PASTA do index.html.
  // O Outlook Classic (motor do Word) carrega imagens por caminho de arquivo
  // (file:///) ou URL, mas NÃO por base64. Por isso a cópia para o Outlook aponta para eles.
  const LOGO_FILE_RED = "logo-vermelha.png";
  const LOGO_FILE_BLUE = "logo-azul.jpg";

  // Largura da logo em cada modelo (px). A altura é calculada proporcionalmente.
  const LOGO_WIDTH_BY_TEMPLATE = { classic: 450, executive: 420, compact: 380, card: 440 };

  // Upload de logo/foto personalizada
  const UPLOAD_MAX_BYTES = 2 * 1024 * 1024;
  const UPLOAD_ALLOWED_TYPES = ["image/png", "image/jpeg", "image/gif"];
  const UPLOAD_MAX_WIDTH = 450;

  // Paleta padrão e presets válidos
  const DEFAULT_PRIMARY = "#0000cc";
  const DEFAULT_SECONDARY = "#cc0000";

  const FONT = "font-family: Verdana, Geneva, sans-serif; font-size: 11pt; font-weight: bold;";
  const CONTACT_COLOR = "#4a4e69";

  const STORAGE_KEY = "federal_safety_sig_state";
  const STORAGE_KEY_CUSTOM_LOGO = "federal_safety_sig_custom_logo";

  // Cache dos elementos DOM
  const dom = {
    inputNome: document.getElementById("inputNome"),
    inputCargo: document.getElementById("inputCargo"),
    inputLogoColor: document.getElementById("inputLogoColor"),
    inputTelefone: document.getElementById("inputTelefone"),
    inputEmail: document.getElementById("inputEmail"),
    chkShowTelefone: document.getElementById("chkShowTelefone"),
    chkShowEmail: document.getElementById("chkShowEmail"),
    inputEmpresa: document.getElementById("inputEmpresa"),
    inputSite: document.getElementById("inputSite"),
    inputSlogan: document.getElementById("inputSlogan"),
    inputCustomLogo: document.getElementById("inputCustomLogo"),
    btnResetLogo: document.getElementById("btnResetLogo"),
    mediaActions: document.getElementById("mediaActions"),
    signatureContainer: document.getElementById("signatureContainer"),
    toastMessage: document.getElementById("toastMessage"),
    codeTextarea: document.getElementById("codeTextarea"),
    // Modais
    modalCode: document.getElementById("modalCode"),
    btnCloseModalCode: document.getElementById("btnCloseModalCode"),
    btnCopyModalCode: document.getElementById("btnCopyModalCode"),
    modalLocawebHelp: document.getElementById("modalLocawebHelp"),
    btnCloseModalLocaweb: document.getElementById("btnCloseModalLocaweb"),
    btnOkLocawebHelp: document.getElementById("btnOkLocawebHelp"),
    modalOutlookHelp: document.getElementById("modalOutlookHelp"),
    btnCloseModalOutlook: document.getElementById("btnCloseModalOutlook"),
    btnOkOutlookHelp: document.getElementById("btnOkOutlookHelp"),
    // Botões Principais
    btnCopyHtmlLocaweb: document.getElementById("btnCopyHtmlLocaweb"),
    btnCopyVisual: document.getElementById("btnCopyVisual"),
    btnCopyLogo: document.getElementById("btnCopyLogo"),
    btnViewCode: document.getElementById("btnViewCode"),
    btnDownloadHtml: document.getElementById("btnDownloadHtml"),
  };

  // Estado da Aplicação
  let state = {
    nome: "Michel Berigo",
    cargo: "Auxiliar de Monitoramento",
    logoColor: "blue",
    showTelefone: false,
    showEmail: false,
    telefone: "(11) 98765-4321",
    email: "michel.berigo@federalst.com.br",
    empresa: "FEDERAL SAFETY",
    site: "www.federalst.com.br",
    slogan: "Promova gentilezas. Retribua gentilezas.",
    template: "classic",
    colorPrimary: DEFAULT_PRIMARY,
    colorSecondary: DEFAULT_SECONDARY,
    // Logo personalizada (base64 já redimensionada) e suas dimensões
    customLogo: null,
    customLogoW: 0,
    customLogoH: 0,
  };

  // ==========================================================================
  // 1. UTILITÁRIOS DE SEGURANÇA / FORMATAÇÃO
  // ==========================================================================

  // Escapa texto para uso seguro em HTML (conteúdo e atributos).
  // Caracteres não-ASCII (acentos etc.) viram entidades numéricas, o que
  // evita problemas de codificação em qualquer cliente de e-mail.
  function escapeHtml(str) {
    if (str === null || str === undefined) return "";
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;")
      .replace(/[^\x00-\x7F]/g, (ch) => `&#${ch.codePointAt(0)};`);
  }

  // Normaliza o site para um link https:// válido
  function cleanSiteUrl(url) {
    const fallback = "https://www.federalst.com.br";
    if (!url) return fallback;
    let formatted = url.trim().replace(/\s+/g, "");
    if (!/^https?:\/\//i.test(formatted)) formatted = "https://" + formatted;
    try {
      const u = new URL(formatted);
      return u.protocol === "http:" || u.protocol === "https:" ? u.href : fallback;
    } catch (e) {
      return fallback;
    }
  }

  function isValidEmail(email) {
    return /^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}$/.test(email || "");
  }

  function phoneToTelHref(phone) {
    const digits = (phone || "").replace(/[^\d+]/g, "");
    if (!digits) return "";
    return "tel:" + (digits.startsWith("+") ? digits : "+55" + digits.replace(/^0+/, ""));
  }

  // Máscara simples de telefone brasileiro: (11) 98765-4321 / (11) 3456-7890
  function maskPhone(value) {
    const d = (value || "").replace(/\D/g, "").slice(0, 11);
    if (d.length <= 2) return d.length ? `(${d}` : "";
    if (d.length <= 6) return `(${d.slice(0, 2)}) ${d.slice(2)}`;
    if (d.length <= 10) return `(${d.slice(0, 2)}) ${d.slice(2, 6)}-${d.slice(6)}`;
    return `(${d.slice(0, 2)}) ${d.slice(2, 7)}-${d.slice(7)}`;
  }

  function isHexColor(c) {
    return /^#[0-9a-f]{6}$/i.test(c || "");
  }

  // ==========================================================================
  // 2. LOGO: ORIGEM CONFORME O DESTINO (Locaweb / Outlook)
  // ==========================================================================

  function getPublicLogoUrl() {
    const url = state.logoColor === "red" ? LOGO_URL_RED : LOGO_URL_BLUE;
    return url && /^https:\/\//i.test(url) ? url : "";
  }

  // Retorna { src, naturalW, naturalH } da logo para o destino informado,
  // ou null quando a logo não pode ser incluída (logo personalizada no Outlook).
  //   target "web"     -> pré-visualização, Locaweb, download, código fonte
  //   target "outlook" -> cópia para o Outlook Classic
  function getLogoSource(target) {
    if (state.customLogo) {
      if (target === "outlook") return null; // base64 não funciona no Outlook Classic
      return { src: state.customLogo, naturalW: state.customLogoW, naturalH: state.customLogoH };
    }

    const isRed = state.logoColor === "red";
    const dims = { naturalW: OFFICIAL_LOGO_W, naturalH: OFFICIAL_LOGO_H };
    const publicUrl = getPublicLogoUrl();
    if (publicUrl) return { src: publicUrl, ...dims };

    if (target === "outlook") {
      try {
        const fileUrl = new URL(isRed ? LOGO_FILE_RED : LOGO_FILE_BLUE, window.location.href).href;
        return { src: fileUrl, ...dims };
      } catch (e) {
        return null;
      }
    }
    return { src: isRed ? LOGO_RED : LOGO_BLUE, ...dims };
  }

  // ==========================================================================
  // 3. MODELOS HTML (Verdana 11pt, negrito)
  // Todos os modelos usam layout em TABELA com estilos inline: é o formato
  // compatível ao mesmo tempo com o webmail da Locaweb e com o Outlook Classic
  // (motor do Word), que ignora max-width, border-radius e margens de <p>.
  // Há UMA única fonte por modelo, usada pelos dois destinos.
  // ==========================================================================

  function textRow(content, color, paddingBottom) {
    return `<tr><td style="${FONT} color: ${color}; padding: 0 0 ${paddingBottom}px 0; mso-line-height-rule: exactly; line-height: 1.4;">${content}</td></tr>`;
  }

  function logoRow(logo, width, paddingBottom) {
    if (!logo) return "";
    const w = Math.min(width, logo.naturalW || width);
    const h = logo.naturalW ? Math.round((logo.naturalH * w) / logo.naturalW) : "";
    const hAttr = h ? ` height="${h}"` : "";
    const hCss = h ? ` height: ${h}px;` : " height: auto;";
    return `<tr><td style="padding: 0 0 ${paddingBottom}px 0;"><img src="${escapeHtml(logo.src)}" alt="Federal Safety" width="${w}"${hAttr} border="0" style="display: block; border: 0; width: ${w}px;${hCss}" /></td></tr>`;
  }

  function linkHtml(href, text, color) {
    return `<a href="${escapeHtml(href)}" target="_blank" rel="noopener noreferrer" style="color: ${color}; text-decoration: underline; font-weight: bold;">${escapeHtml(text)}</a>`;
  }

  // Monta a linha de contatos (telefone e/ou e-mail) conforme os checkboxes
  function buildContactContent(s, withLabels, separator) {
    const parts = [];
    if (s.showTelefone && s.telefone) {
      const tel = phoneToTelHref(s.telefone);
      const telText = escapeHtml(s.telefone);
      const telHtml = tel
        ? `<a href="${escapeHtml(tel)}" style="color: ${CONTACT_COLOR}; text-decoration: none; font-weight: bold;">${telText}</a>`
        : telText;
      parts.push((withLabels ? "Tel: " : "") + telHtml);
    }
    if (s.showEmail && s.email) {
      const emailHtml = isValidEmail(s.email)
        ? linkHtml("mailto:" + s.email, s.email, s.colorPrimary)
        : escapeHtml(s.email);
      parts.push((withLabels ? "E-mail: " : "") + emailHtml);
    }
    return parts.join(separator);
  }

  function wrapTable(rows, width) {
    return `<table border="0" cellpadding="0" cellspacing="0" width="${width}" style="border-collapse: collapse; mso-table-lspace: 0pt; mso-table-rspace: 0pt; ${FONT}">${rows}</table>`;
  }

  // MODELO 1: CLÁSSICO OFICIAL
  function buildClassicHTML(s, logo) {
    const contact = buildContactContent(s, true, " &bull; ");
    const slogan = s.slogan || "Promova gentilezas. Retribua gentilezas.";
    const rows = [
      textRow("&Agrave; disposi&ccedil;&atilde;o,", s.colorPrimary, 12),
      textRow(`${escapeHtml(s.nome)} &ndash; ${escapeHtml(s.cargo)} - ${escapeHtml(s.empresa)}`, s.colorSecondary, 12),
      logoRow(logo, LOGO_WIDTH_BY_TEMPLATE.classic, 12),
      contact ? textRow(contact, CONTACT_COLOR, 10) : "",
      textRow(`&quot;${escapeHtml(slogan)}&quot;`, s.colorSecondary, 10),
      textRow(`Visite o novo site ${linkHtml(cleanSiteUrl(s.site), s.site, s.colorPrimary)} e conhe&ccedil;a nossos servi&ccedil;os!`, s.colorSecondary, 0),
    ].join("");
    return wrapTable(rows, LOGO_WIDTH_BY_TEMPLATE.classic);
  }

  // MODELO 2: EXECUTIVO (barra lateral colorida)
  function buildExecutiveHTML(s, logo) {
    const contact = buildContactContent(s, true, " | ");
    const inner = [
      textRow(escapeHtml(s.nome), s.colorPrimary, 4),
      textRow(`${escapeHtml(s.cargo)} &ndash; ${escapeHtml(s.empresa)}`, s.colorSecondary, 10),
      logoRow(logo, LOGO_WIDTH_BY_TEMPLATE.executive, 10),
      contact ? textRow(contact, CONTACT_COLOR, 8) : "",
      s.slogan ? textRow(`&quot;${escapeHtml(s.slogan)}&quot;`, s.colorSecondary, 8) : "",
      textRow(`Acesse ${linkHtml(cleanSiteUrl(s.site), s.site, s.colorPrimary)}`, s.colorSecondary, 0),
    ].join("");
    const totalW = LOGO_WIDTH_BY_TEMPLATE.executive + 18;
    const rows = [
      textRow("&Agrave; disposi&ccedil;&atilde;o,", s.colorPrimary, 10),
      `<tr><td style="padding: 0;"><table border="0" cellpadding="0" cellspacing="0" style="border-collapse: collapse; mso-table-lspace: 0pt; mso-table-rspace: 0pt;"><tr>` +
        `<td width="4" bgcolor="${s.colorPrimary}" style="width: 4px; background-color: ${s.colorPrimary}; font-size: 1px; line-height: 1px;">&nbsp;</td>` +
        `<td width="14" style="width: 14px; font-size: 1px; line-height: 1px;">&nbsp;</td>` +
        `<td style="padding: 0;"><table border="0" cellpadding="0" cellspacing="0" style="border-collapse: collapse; ${FONT}">${inner}</table></td>` +
      `</tr></table></td></tr>`,
    ].join("");
    return wrapTable(rows, totalW);
  }

  // MODELO 3: COMPACTO
  function buildCompactHTML(s, logo) {
    const contact = buildContactContent(s, false, " &bull; ");
    const sloganPart = s.slogan ? `${escapeHtml(s.slogan)} | ` : "";
    const rows = [
      textRow(`<span style="color: ${s.colorPrimary}; font-weight: bold;">${escapeHtml(s.nome)}</span> &ndash; ${escapeHtml(s.cargo)} - ${escapeHtml(s.empresa)}`, s.colorSecondary, 8),
      logoRow(logo, LOGO_WIDTH_BY_TEMPLATE.compact, 8),
      contact ? textRow(contact, CONTACT_COLOR, 6) : "",
      textRow(`${sloganPart}${linkHtml(cleanSiteUrl(s.site), s.site, s.colorPrimary)}`, s.colorSecondary, 0),
    ].join("");
    return wrapTable(rows, LOGO_WIDTH_BY_TEMPLATE.compact);
  }

  // MODELO 4: CARTÃO DIGITAL (com borda)
  function buildCardHTML(s, logo) {
    const contact = buildContactContent(s, true, " | ");
    const inner = [
      textRow(escapeHtml(s.nome), s.colorPrimary, 4),
      textRow(`${escapeHtml(s.cargo)} &bull; ${escapeHtml(s.empresa)}`, s.colorSecondary, 8),
      contact ? textRow(contact, CONTACT_COLOR, 10) : "",
      logoRow(logo, LOGO_WIDTH_BY_TEMPLATE.card, 10),
      s.slogan ? textRow(`&quot;${escapeHtml(s.slogan)}&quot;`, s.colorSecondary, 4) : "",
      textRow(`Website: ${linkHtml(cleanSiteUrl(s.site), s.site, s.colorPrimary)}`, s.colorSecondary, 0),
    ].join("");
    const totalW = LOGO_WIDTH_BY_TEMPLATE.card + 30;
    return `<table border="0" cellpadding="0" cellspacing="0" width="${totalW}" style="border-collapse: collapse; border: 1px solid #dfe3ee; mso-table-lspace: 0pt; mso-table-rspace: 0pt;"><tr><td style="padding: 14px;"><table border="0" cellpadding="0" cellspacing="0" style="border-collapse: collapse; ${FONT}">${inner}</table></td></tr></table>`;
  }

  // Gera o HTML do modelo atual para o destino ("web" ou "outlook")
  function getGeneratedHTML(target) {
    const logo = getLogoSource(target || "web");
    switch (state.template) {
      case "executive": return buildExecutiveHTML(state, logo);
      case "compact": return buildCompactHTML(state, logo);
      case "card": return buildCardHTML(state, logo);
      case "classic":
      default: return buildClassicHTML(state, logo);
    }
  }

  // Versão do código para EXIBIÇÃO no modal (base64 abreviado para ficar legível).
  // O botão de copiar do modal copia sempre o código COMPLETO.
  function abbreviateBase64(html) {
    return html.replace(/data:image\/[a-z+]+;base64,[A-Za-z0-9+/=]+/g, (m) =>
      `${m.slice(0, m.indexOf(",") + 1)}[...imagem base64 com ${Math.round(m.length / 1024)} KB...]`);
  }

  // ==========================================================================
  // 4. CARREGAR E SALVAR ESTADO (LOCAL STORAGE)
  // A logo oficial NÃO é salva (já está no código). Só a personalizada,
  // em chave separada, e com aviso caso o navegador não tenha espaço.
  // ==========================================================================

  function loadSavedState() {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        const p = JSON.parse(saved);
        const textFields = ["nome", "cargo", "telefone", "email", "empresa", "site", "slogan"];
        textFields.forEach((k) => { if (typeof p[k] === "string") state[k] = p[k]; });
        state.logoColor = p.logoColor === "red" ? "red" : "blue";
        state.showTelefone = !!p.showTelefone;
        state.showEmail = !!p.showEmail;
        if (["classic", "executive", "compact", "card"].includes(p.template)) state.template = p.template;

        // Só aceita cores que correspondam a um preset existente
        const preset = findColorPreset(p.colorPrimary, p.colorSecondary);
        if (preset) {
          state.colorPrimary = preset.dataset.primary;
          state.colorSecondary = preset.dataset.secondary;
        }
      }

      const custom = localStorage.getItem(STORAGE_KEY_CUSTOM_LOGO);
      if (custom) {
        const c = JSON.parse(custom);
        if (c && typeof c.src === "string" && c.src.startsWith("data:image/")) {
          state.customLogo = c.src;
          state.customLogoW = c.w || 0;
          state.customLogoH = c.h || 0;
        }
      }
      // Limpa resíduo de versões antigas que gravavam a logo dentro do estado
      if (saved && saved.includes("currentLogo")) saveState();
    } catch (e) {
      console.warn("Não foi possível carregar dados salvos:", e);
    }
    syncFormFromState();
  }

  function saveState() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({
        nome: state.nome,
        cargo: state.cargo,
        logoColor: state.logoColor,
        showTelefone: state.showTelefone,
        showEmail: state.showEmail,
        telefone: state.telefone,
        email: state.email,
        empresa: state.empresa,
        site: state.site,
        slogan: state.slogan,
        template: state.template,
        colorPrimary: state.colorPrimary,
        colorSecondary: state.colorSecondary,
      }));
    } catch (e) {
      console.warn("Erro ao salvar dados localmente:", e);
    }
  }

  function saveCustomLogo() {
    try {
      if (state.customLogo) {
        localStorage.setItem(STORAGE_KEY_CUSTOM_LOGO, JSON.stringify({
          src: state.customLogo, w: state.customLogoW, h: state.customLogoH,
        }));
      } else {
        localStorage.removeItem(STORAGE_KEY_CUSTOM_LOGO);
      }
      return true;
    } catch (e) {
      console.warn("Logo personalizada não pôde ser salva:", e);
      return false;
    }
  }

  function findColorPreset(primary, secondary) {
    if (!isHexColor(primary) || !isHexColor(secondary)) return null;
    return Array.from(document.querySelectorAll(".color-btn")).find((b) =>
      b.dataset.primary.toLowerCase() === primary.toLowerCase() &&
      b.dataset.secondary.toLowerCase() === secondary.toLowerCase()) || null;
  }

  // Reflete o estado nos campos do formulário
  function syncFormFromState() {
    if (dom.inputNome) dom.inputNome.value = state.nome;
    if (dom.inputCargo) dom.inputCargo.value = state.cargo;
    if (dom.inputLogoColor) dom.inputLogoColor.value = state.logoColor;
    if (dom.inputTelefone) dom.inputTelefone.value = state.telefone;
    if (dom.inputEmail) dom.inputEmail.value = state.email;
    if (dom.chkShowTelefone) dom.chkShowTelefone.checked = state.showTelefone;
    if (dom.chkShowEmail) dom.chkShowEmail.checked = state.showEmail;
    if (dom.inputEmpresa) dom.inputEmpresa.value = state.empresa;
    if (dom.inputSite) dom.inputSite.value = state.site;
    if (dom.inputSlogan) dom.inputSlogan.value = state.slogan;

    const rad = document.querySelector(`input[name="templateSelect"][value="${state.template}"]`);
    if (rad) {
      rad.checked = true;
      document.querySelectorAll(".template-card").forEach((c) => c.classList.remove("active"));
      rad.closest(".template-card").classList.add("active");
    }

    const preset = findColorPreset(state.colorPrimary, state.colorSecondary);
    document.querySelectorAll(".color-btn").forEach((b) => b.classList.toggle("active", b === preset));

    if (dom.mediaActions) dom.mediaActions.style.display = state.customLogo ? "block" : "none";
  }

  // ==========================================================================
  // 5. RENDERIZAÇÃO
  // ==========================================================================

  function readFormIntoState() {
    const val = (el, def) => (el ? (el.value || "").trim() || def : def);
    state.nome = val(dom.inputNome, "Michel Berigo");
    state.cargo = val(dom.inputCargo, "Auxiliar de Monitoramento");
    state.logoColor = dom.inputLogoColor && dom.inputLogoColor.value === "red" ? "red" : "blue";
    state.showTelefone = dom.chkShowTelefone ? dom.chkShowTelefone.checked : false;
    state.showEmail = dom.chkShowEmail ? dom.chkShowEmail.checked : false;
    state.telefone = val(dom.inputTelefone, "");
    state.email = val(dom.inputEmail, "");
    state.empresa = val(dom.inputEmpresa, "FEDERAL SAFETY");
    state.site = val(dom.inputSite, "www.federalst.com.br");
    state.slogan = val(dom.inputSlogan, "");
  }

  let saveTimer = null;

  function updateRender() {
    readFormIntoState();

    if (dom.signatureContainer) {
      dom.signatureContainer.innerHTML = getGeneratedHTML("web");
    }

    // Aviso visual de e-mail inválido
    if (dom.inputEmail) {
      const invalid = state.showEmail && state.email && !isValidEmail(state.email);
      dom.inputEmail.classList.toggle("input-invalid", !!invalid);
    }

    // Salva com pequeno atraso para não gravar a cada tecla
    clearTimeout(saveTimer);
    saveTimer = setTimeout(saveState, 400);
  }

  // ==========================================================================
  // 6. EVENTOS
  // ==========================================================================

  function initEvents() {
    const inputs = [
      dom.inputNome, dom.inputCargo, dom.inputLogoColor,
      dom.inputTelefone, dom.inputEmail, dom.inputEmpresa,
      dom.inputSite, dom.inputSlogan, dom.chkShowTelefone,
      dom.chkShowEmail,
    ];
    inputs.forEach((input) => {
      if (input) {
        input.addEventListener("input", updateRender);
        input.addEventListener("change", updateRender);
      }
    });

    // Máscara do telefone
    if (dom.inputTelefone) {
      dom.inputTelefone.addEventListener("input", () => {
        const masked = maskPhone(dom.inputTelefone.value);
        if (masked !== dom.inputTelefone.value) dom.inputTelefone.value = masked;
      });
    }

    // Abas do formulário
    const tabBtns = document.querySelectorAll(".tab-btn");
    tabBtns.forEach((btn) => {
      btn.addEventListener("click", () => {
        tabBtns.forEach((b) => {
          b.classList.remove("active");
          b.setAttribute("aria-selected", "false");
        });
        document.querySelectorAll(".tab-content").forEach((c) => c.classList.remove("active"));
        btn.classList.add("active");
        btn.setAttribute("aria-selected", "true");
        const targetTab = document.getElementById(btn.dataset.tab);
        if (targetTab) targetTab.classList.add("active");
      });
    });

    // Modelos
    document.querySelectorAll('input[name="templateSelect"]').forEach((radio) => {
      radio.addEventListener("change", (e) => {
        state.template = e.target.value;
        document.querySelectorAll(".template-card").forEach((card) => card.classList.remove("active"));
        e.target.closest(".template-card").classList.add("active");
        updateRender();
      });
    });

    // Cores
    const colorBtns = document.querySelectorAll(".color-btn");
    colorBtns.forEach((btn) => {
      btn.addEventListener("click", () => {
        colorBtns.forEach((b) => b.classList.remove("active"));
        btn.classList.add("active");
        state.colorPrimary = btn.dataset.primary;
        state.colorSecondary = btn.dataset.secondary;
        updateRender();
      });
    });

    // Upload de logo/foto personalizada
    if (dom.inputCustomLogo) {
      dom.inputCustomLogo.addEventListener("change", (e) => {
        const file = e.target.files[0];
        if (!file) return;
        if (!UPLOAD_ALLOWED_TYPES.includes(file.type)) {
          showToast("Formato não suportado em e-mails. Use PNG, JPG ou GIF.", "info");
          dom.inputCustomLogo.value = "";
          return;
        }
        if (file.size > UPLOAD_MAX_BYTES) {
          showToast("A imagem deve ter no máximo 2MB.", "info");
          dom.inputCustomLogo.value = "";
          return;
        }
        const reader = new FileReader();
        reader.onload = (event) => {
          resizeImage(event.target.result, file.type, UPLOAD_MAX_WIDTH)
            .then(({ src, w, h }) => {
              state.customLogo = src;
              state.customLogoW = w;
              state.customLogoH = h;
              if (dom.mediaActions) dom.mediaActions.style.display = "block";
              updateRender();
              if (saveCustomLogo()) {
                showToast("Logo/Foto personalizada carregada com sucesso!", "success");
              } else {
                showToast("Logo carregada, mas não foi salva no navegador (sem espaço). Será perdida ao recarregar.", "info");
              }
            })
            .catch(() => showToast("Não foi possível processar a imagem.", "info"));
        };
        reader.readAsDataURL(file);
      });
    }

    if (dom.btnResetLogo) {
      dom.btnResetLogo.addEventListener("click", () => {
        state.customLogo = null;
        state.customLogoW = 0;
        state.customLogoH = 0;
        saveCustomLogo();
        if (dom.mediaActions) dom.mediaActions.style.display = "none";
        if (dom.inputCustomLogo) dom.inputCustomLogo.value = "";
        updateRender();
        showToast("Logo oficial restaurada.", "info");
      });
    }

    // Copiar código HTML (Locaweb)
    if (dom.btnCopyHtmlLocaweb) {
      dom.btnCopyHtmlLocaweb.addEventListener("click", () => {
        updateRender();
        copyTextToClipboard(getGeneratedHTML("web"), () => {
          showToast("Código HTML copiado! Cole no editor da Locaweb.", "success");
          openModal(dom.modalLocawebHelp);
        });
      });
    }

    // Copiar assinatura formatada (Outlook Classic)
    if (dom.btnCopyVisual) {
      dom.btnCopyVisual.addEventListener("click", () => {
        updateRender();
        copyFormattedHTMLString(getGeneratedHTML("outlook"), () => {
          if (state.customLogo) {
            showToast("Logo personalizada não vai junto: use \"Copiar Logo\" e cole a imagem no Outlook.", "info");
          } else {
            showToast("Assinatura copiada! Cole (Ctrl+V) no Outlook.", "success");
          }
          openModal(dom.modalOutlookHelp);
        });
      });
    }

    // Copiar só a logo como imagem
    if (dom.btnCopyLogo) {
      dom.btnCopyLogo.addEventListener("click", () => {
        const src = state.customLogo || (state.logoColor === "red" ? LOGO_RED : LOGO_BLUE);
        copyImageToClipboard(src, () => {
          showToast("Logo copiada! Cole (Ctrl+V) na assinatura do Outlook.", "success");
        });
      });
    }

    // Ver código fonte
    if (dom.btnViewCode) {
      dom.btnViewCode.addEventListener("click", () => {
        updateRender();
        if (dom.codeTextarea) dom.codeTextarea.value = abbreviateBase64(getGeneratedHTML("web"));
        openModal(dom.modalCode);
      });
    }

    // Baixar .html (documento completo com charset)
    if (dom.btnDownloadHtml) {
      dom.btnDownloadHtml.addEventListener("click", () => {
        updateRender();
        const doc = `<!DOCTYPE html>\n<html lang="pt-BR">\n<head>\n<meta charset="utf-8">\n<title>Assinatura - ${escapeHtml(state.nome)}</title>\n</head>\n<body>\n${getGeneratedHTML("web")}\n</body>\n</html>\n`;
        const blob = new Blob([doc], { type: "text/html;charset=utf-8" });
        const url = URL.createObjectURL(blob);
        const link = document.createElement("a");
        const slug = state.nome.normalize("NFD").replace(/[\u0300-\u036f]/g, "")
          .toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "assinatura";
        link.href = url;
        link.download = `assinatura-federal-safety-${slug}.html`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        setTimeout(() => URL.revokeObjectURL(url), 1000);
        showToast("Arquivo HTML baixado com sucesso!", "success");
      });
    }

    // Modais
    if (dom.btnCloseModalCode) dom.btnCloseModalCode.addEventListener("click", () => closeModal(dom.modalCode));
    if (dom.btnCopyModalCode) {
      dom.btnCopyModalCode.addEventListener("click", () => {
        copyTextToClipboard(getGeneratedHTML("web"), () => {
          showToast("Código HTML copiado com sucesso!", "success");
          closeModal(dom.modalCode);
        });
      });
    }
    if (dom.btnCloseModalLocaweb) dom.btnCloseModalLocaweb.addEventListener("click", () => closeModal(dom.modalLocawebHelp));
    if (dom.btnOkLocawebHelp) dom.btnOkLocawebHelp.addEventListener("click", () => closeModal(dom.modalLocawebHelp));
    if (dom.btnCloseModalOutlook) dom.btnCloseModalOutlook.addEventListener("click", () => closeModal(dom.modalOutlookHelp));
    if (dom.btnOkOutlookHelp) dom.btnOkOutlookHelp.addEventListener("click", () => closeModal(dom.modalOutlookHelp));

    const modals = [dom.modalCode, dom.modalLocawebHelp, dom.modalOutlookHelp];
    window.addEventListener("click", (e) => {
      modals.forEach((m) => { if (e.target === m) closeModal(m); });
    });
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape") modals.forEach(closeModal);
    });
  }

  // ==========================================================================
  // 7. ÁREA DE TRANSFERÊNCIA
  // ==========================================================================

  // Copia texto puro (código HTML para a Locaweb)
  function copyTextToClipboard(text, successCallback) {
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(text).then(successCallback).catch(() => fallbackCopyText(text, successCallback));
    } else {
      fallbackCopyText(text, successCallback);
    }
  }

  function fallbackCopyText(text, successCallback) {
    const textarea = document.createElement("textarea");
    textarea.value = text;
    textarea.style.position = "fixed";
    textarea.style.opacity = "0";
    document.body.appendChild(textarea);
    textarea.focus();
    textarea.select();
    let ok = false;
    try {
      ok = document.execCommand("copy");
    } catch (err) {
      ok = false;
    }
    document.body.removeChild(textarea);
    if (ok) {
      if (successCallback) successCallback();
    } else {
      showToast("Não foi possível copiar automaticamente. Use \"Ver Código Fonte\" e copie com Ctrl+C.", "info");
    }
  }

  // Copia HTML formatado (Outlook).
  // Método principal: renderiza num elemento temporário e copia a SELEÇÃO
  // (o navegador gera o formato CF_HTML completo, que o Word/Outlook lê melhor).
  // execCommand é descontinuado, mas ainda suportado no Chrome/Edge; se falhar,
  // usa a Clipboard API (text/html) como alternativa.
  function copyFormattedHTMLString(html, successCallback) {
    if (selectionCopy(html)) {
      if (successCallback) successCallback();
      return;
    }

    if (navigator.clipboard && window.ClipboardItem) {
      const fullHtml = `<html><head><meta charset="utf-8"></head><body>${html}</body></html>`;
      const item = new ClipboardItem({
        "text/html": new Blob([fullHtml], { type: "text/html" }),
        "text/plain": new Blob([htmlToPlainText(html)], { type: "text/plain" }),
      });
      navigator.clipboard.write([item])
        .then(() => successCallback && successCallback())
        .catch(() => showToast("Seu navegador não permite cópia formatada. Use Chrome ou Edge.", "info"));
    } else {
      showToast("Seu navegador não permite cópia formatada. Use Chrome ou Edge.", "info");
    }
  }

  function selectionCopy(html) {
    const temp = document.createElement("div");
    temp.innerHTML = html;
    temp.setAttribute("contenteditable", "true");
    temp.style.position = "fixed";
    temp.style.left = "-9999px";
    temp.style.top = "0";
    temp.style.background = "#ffffff";
    document.body.appendChild(temp);

    const selection = window.getSelection();
    const range = document.createRange();
    range.selectNodeContents(temp);
    selection.removeAllRanges();
    selection.addRange(range);

    let ok = false;
    try {
      ok = document.execCommand("copy");
    } catch (e) {
      ok = false;
    }
    selection.removeAllRanges();
    document.body.removeChild(temp);
    return ok;
  }

  function htmlToPlainText(html) {
    const div = document.createElement("div");
    div.innerHTML = html.replace(/<\/tr>/g, "</tr>\n");
    return (div.textContent || "").replace(/\n\s*\n/g, "\n").trim();
  }

  // Copia uma imagem (data URL) como PNG para a área de transferência.
  function copyImageToClipboard(dataUrl, successCallback) {
    if (!navigator.clipboard || !window.ClipboardItem) {
      showToast("Seu navegador não permite copiar imagens. Use Chrome ou Edge.", "info");
      return;
    }
    loadImage(dataUrl)
      .then((img) => {
        const canvas = drawToCanvas(img, Math.min(450, img.naturalWidth));
        canvas.toBlob((blob) => {
          if (!blob) {
            showToast("Erro ao preparar a imagem da logo.", "info");
            return;
          }
          navigator.clipboard.write([new ClipboardItem({ "image/png": blob })])
            .then(() => successCallback && successCallback())
            .catch(() => showToast("Não foi possível copiar a logo. Clique com o botão direito na logo da pré-visualização e escolha \"Copiar imagem\".", "info"));
        }, "image/png");
      })
      .catch(() => showToast("Erro ao carregar a logo.", "info"));
  }

  // ==========================================================================
  // 8. IMAGENS (redimensionamento)
  // ==========================================================================

  function loadImage(src) {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = reject;
      img.src = src;
    });
  }

  function drawToCanvas(img, targetW, keepTransparency) {
    const scale = targetW / img.naturalWidth;
    const canvas = document.createElement("canvas");
    canvas.width = Math.max(1, Math.round(img.naturalWidth * scale));
    canvas.height = Math.max(1, Math.round(img.naturalHeight * scale));
    const ctx = canvas.getContext("2d");
    if (!keepTransparency) {
      ctx.fillStyle = "#ffffff";
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }
    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
    return canvas;
  }

  // Redimensiona para no máximo maxW de largura (2x para telas de alta densidade
  // não é usado de propósito: mantém a assinatura leve).
  function resizeImage(dataUrl, mimeType, maxW) {
    return loadImage(dataUrl).then((img) => {
      const w = Math.min(maxW, img.naturalWidth);
      const isPng = mimeType === "image/png" || mimeType === "image/gif";
      const canvas = drawToCanvas(img, w, isPng);
      const src = isPng ? canvas.toDataURL("image/png") : canvas.toDataURL("image/jpeg", 0.9);
      return { src, w: canvas.width, h: canvas.height };
    });
  }

  // ==========================================================================
  // 9. UI (toast e modais)
  // ==========================================================================

  let toastTimer = null;

  function showToast(msg, type = "success") {
    if (!dom.toastMessage) return;
    clearTimeout(toastTimer);
    dom.toastMessage.textContent = msg;
    dom.toastMessage.className = `toast-message toast-${type} show`;
    toastTimer = setTimeout(() => {
      dom.toastMessage.classList.remove("show");
    }, 5000);
  }

  function openModal(modal) {
    if (modal) {
      modal.classList.add("active");
      modal.setAttribute("aria-hidden", "false");
    }
  }

  function closeModal(modal) {
    if (modal) {
      modal.classList.remove("active");
      modal.setAttribute("aria-hidden", "true");
    }
  }

  document.addEventListener("DOMContentLoaded", () => {
    loadSavedState();
    initEvents();
    updateRender();
  });
})();
